124	const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
125	/** Exactly these three permissions (spec 7.5): create and delete of `plan`, and `country.find` for the relation. */
126	export const PLAN_TOKEN_SCOPE = ['api::plan.plan.create', 'api::plan.plan.delete', 'api::country.country.find'];
