179	/** Pre-test cleanup: deletes published plans left with the test's key by a crashed run (read is public). */
180	export async function deleteStalePlans(api: APIRequestContext, token: ScopedToken, key: string): Promise<void> {
181	  const response = await api.get('/api/plans', { params: { 'filters[key][$eq]': key, 'pagination[pageSize]': '100' } });
182	  await expectOk(response, 'Reading leftover plans');
183	  const body = (await response.json()) as { data?: { documentId?: string }[] };
184	  for (const stale of body.data ?? []) {
185	    if (stale.documentId) await deletePlan(api, token, stale.documentId);
186	  }
187	}
