224	  // The date control reads typed digits in the browser locale; the first segment is the month in en-US.
225	  test.use({ locale: 'en-US', viewport: { width: 1280, height: 800 } });
226	
227	  /** The description of what has focus: a button by its text, a plan option as "plan group". */
228	  async function focused(page: Page): Promise<string> {
229	    return page.evaluate(() => {
230	      const el = document.activeElement as HTMLElement | null;
231	      if (!el) return 'none';
232	      if (el.tagName === 'BUTTON') return (el.textContent ?? '').trim();
233	      if (el.tagName === 'INPUT' && (el as HTMLInputElement).type === 'radio') return 'plan group';
234	      return el.tagName.toLowerCase();
235	    });
236	  }
237	
238	  async function expectVisibleFocusIndicator(page: Page): Promise<void> {
239	    const visible = await page.evaluate(() => {
240	      const el = document.activeElement as HTMLElement;
241	      const style = getComputedStyle(el);
242	      const outline = style.outlineStyle !== 'none' && parseFloat(style.outlineWidth) > 0;
243	      const shadow = style.boxShadow !== 'none';
244	      return outline || shadow;
245	    });
246	    expect(visible, 'a focused control must show a visible focus indicator').toBe(true);
