1	/**
2	 * DOM helpers for component tests. Queries go through what a person or assistive technology
3	 * perceives: the label text, the button name, the described-by text and the alert regions.
4	 * They never use component classes, ids or internal test hooks.
5	 */
6	
7	/** Label text as a person reads it: whitespace collapsed, the required marker "*" removed. */
8	export function normalise(text: string | null | undefined): string {
9	  return (text ?? '').replace(/\*/g, '').replace(/\s+/g, ' ').trim();
10	}
11	
12	export type Control = HTMLInputElement | HTMLSelectElement;
13	
14	/** All labels of the page, in document order, as text. */
15	export function allLabels(root: ParentNode): string[] {
16	  return Array.from(root.querySelectorAll('label'))
17	    .map((l) => normalise(l.textContent))
18	    .filter((t) => t.length > 0);
19	}
20	
21	/** The control a label names (by `for` or by nesting), or null when no such label exists. */
22	export function maybeControl(root: ParentNode, label: string): Control | null {
23	  for (const l of Array.from(root.querySelectorAll('label'))) {
24	    if (normalise(l.textContent) === label && l.control) return l.control as Control;
25	  }
26	  return null;
27	}
28	
29	export function control(root: ParentNode, label: string): Control {
30	  const found = maybeControl(root, label);
31	  if (!found) throw new Error(`No control is labelled "${label}"`);
32	  return found;
33	}
34	
35	/** Every native control that holds a value (inputs and selects), in document order. */
36	export function allControls(root: ParentNode): Control[] {
37	  return Array.from(root.querySelectorAll<Control>('input, select'));
38	}
39	
40	export function button(root: ParentNode, name: string): HTMLButtonElement {
41	  const found = Array.from(root.querySelectorAll('button')).find((b) => normalise(b.textContent) === name);
42	  if (!found) throw new Error(`No button named "${name}"`);
43	  return found as HTMLButtonElement;
44	}
45	
46	export function maybeButton(root: ParentNode, name: string): HTMLButtonElement | null {
47	  return (Array.from(root.querySelectorAll('button')).find((b) => normalise(b.textContent) === name) as HTMLButtonElement | undefined) ?? null;
48	}
49	
50	export function typeInto(el: Control, text: string): void {
51	  el.value = text;
52	  el.dispatchEvent(new Event('input', { bubbles: true }));
53	}
54	
55	/** Leave a control (the "touched" moment of Signal Forms). */
56	export function leave(el: Control): void {
57	  el.dispatchEvent(new FocusEvent('blur'));
58	  el.dispatchEvent(new FocusEvent('focusout', { bubbles: true }));
59	}
60	
61	/** Pick the option whose visible text matches (a person chooses by what they read). */
62	export function choose(select: HTMLSelectElement, optionText: string): void {
63	  const option = Array.from(select.options).find((o) => normalise(o.textContent) === optionText);
64	  if (!option) throw new Error(`No option "${optionText}"`);
65	  select.value = option.value;
66	  select.dispatchEvent(new Event('input', { bubbles: true }));
67	  select.dispatchEvent(new Event('change', { bubbles: true }));
68	}
69	
70	export function setChecked(el: HTMLInputElement, checked: boolean): void {
71	  if (el.checked !== checked) el.click();
72	}
73	
74	/**
75	 * Fill the form with values keyed by visible label. A `null` value leaves the control untouched.
76	 * Selects take the option text, checkboxes a boolean, everything else a string.
77	 */
78	export function fillForm(root: ParentNode, values: Record<string, string | boolean | null>): void {
79	  for (const [label, value] of Object.entries(values)) {
80	    if (value === null) continue;
81	    const el = control(root, label);
82	    if (el instanceof HTMLSelectElement) {
83	      choose(el, value as string);
84	    } else if (el.type === 'checkbox') {
85	      setChecked(el, value as boolean);
86	    } else {
87	      typeInto(el, value as string);
88	    }
89	  }
90	}
91	
92	/** The text of every element the control points at with aria-describedby (help text, error). */
93	export function describedText(el: Control): string {
94	  const ids = (el.getAttribute('aria-describedby') ?? '').split(/\s+/).filter(Boolean);
95	  return ids
96	    .map((id) => normalise(el.ownerDocument.getElementById(id)?.textContent))
97	    .filter(Boolean)
98	    .join(' ');
99	}
100	
101	/** Non-empty texts of the alert regions of the page. */
102	export function alertTexts(root: ParentNode): string[] {
103	  return Array.from(root.querySelectorAll('[role="alert"]'))
104	    .map((e) => normalise(e.textContent))
105	    .filter((t) => t.length > 0);
106	}
107	
108	/** Controls currently exposed as invalid. */
109	export function invalidControls(root: ParentNode): Control[] {
110	  return allControls(root).filter((c) => c.getAttribute('aria-invalid') === 'true');
111	}
112	
113	export function isExposedAsRequired(el: Control): boolean {
114	  return el.required || el.getAttribute('aria-required') === 'true';
115	}
116	
117	/** The labels of the controls that currently show an error, in document order. */
118	export function labelsWithErrors(root: ParentNode): string[] {
119	  return invalidControls(root).map((c) => normalise(c.labels?.[0]?.textContent));
120	}
121	
122	/** Current value of a control as a person sees it (checkbox: boolean, select: the option text). */
123	export function shownValue(el: Control): string | boolean {
124	  if (el instanceof HTMLSelectElement) return normalise(el.selectedOptions[0]?.textContent);
125	  if (el.type === 'checkbox') return el.checked;
126	  return el.value;
127	}
