1	<main class="page" [attr.aria-busy]="status() === 'loading' ? 'true' : null">
2	  <h1 id="plans-heading" #heading tabindex="-1">Elige tu plan</h1>
3	  @switch (status()) {
4	    @case ('loading') {
5	      <p role="status">Cargando planes…</p>
6	    }
7	    @case ('error') {
8	      <app-load-error message="No pudimos cargar los planes. Intenta de nuevo." (retry)="load()" />
9	    }
10	    @case ('empty') {
11	      <p role="status">No hay planes disponibles para tu país en este momento.</p>
12	    }
13	    @case ('ready') {
14	      <div
15	        class="plans"
16	        role="radiogroup"
17	        aria-labelledby="plans-heading"
18	        aria-required="true"
19	        [attr.aria-describedby]="showChoosePlan() ? 'choose-plan-message' : null"
20	      >
21	        @for (item of items(); track item.plan.key) {
22	          <div class="plan" [class.plan--chosen]="chosenKey() === item.plan.key" [class.plan--recommended]="item.plan.key === recommendedKey()">
23	            <div class="plan__header">
24	              <input
25	                #option
26	                type="radio"
27	                name="plan"
28	                class="plan__radio"
29	                [id]="'plan-' + item.plan.key"
30	                [value]="item.plan.key"
31	                [checked]="chosenKey() === item.plan.key"
32	                [attr.aria-describedby]="describedBy(item.plan.key)"
33	                (change)="choose(item.plan.key)"
34	              />
35	              <h2 class="plan__name">
36	                <label [for]="'plan-' + item.plan.key">{{ item.plan.name }}</label>
37	              </h2>
38	              @if (item.plan.key === recommendedKey()) {
39	                <span class="plan__badge" [id]="'plan-recommended-' + item.plan.key">Recomendado</span>
40	              }
41	              @if (chosenKey() === item.plan.key) {
42	                <span class="plan__badge plan__badge--chosen">Seleccionado</span>
43	              }
44	            </div>
45	            <p class="plan__description" [id]="'plan-description-' + item.plan.key">{{ item.plan.shortDescription }}</p>
46	            <p class="plan__price" [id]="'plan-price-' + item.plan.key">
47	              <span class="plan__amount">{{ item.price }}</span>
48	              <span class="plan__caption">Precio anual</span>
49	            </p>
50	            <h3 class="plan__list-heading">Coberturas</h3>
51	            <ul class="plan__list">
52	              @for (coverage of item.plan.coverages; track $index) {
53	                <li>{{ coverage }}</li>
54	              }
55	            </ul>
56	            @if (item.plan.benefits.length > 0) {
57	              <h3 class="plan__list-heading">Beneficios</h3>
58	              <ul class="plan__list">
59	                @for (benefit of item.plan.benefits; track $index) {
60	                  <li>{{ benefit }}</li>
61	                }
62	              </ul>
63	            }
64	          </div>
65	        }
66	      </div>
67	      @if (showChoosePlan()) {
68	        <p role="alert" id="choose-plan-message" class="choose-message">Elige un plan para continuar.</p>
69	      }
70	    }
71	  }
72	  <div class="actions">
73	    <button type="button" class="secondary" (click)="back()">Atrás</button>
74	    @if (status() === 'ready') {
75	      <button type="button" (click)="next()">Continuar</button>
76	    }
77	  </div>
78	</main>
