2	import { describe, expect, it } from 'vitest';
3	import { readdirSync, readFileSync, statSync } from 'node:fs';
4	import { join } from 'node:path';
5	
6	/**
7	 * The review greps of ADR-0008 and ADR-0009 ("Confirmation"), as tests, so that they run in the
8	 * gate and not only in a reviewer's terminal. They read the production sources of `frontend/src`
9	 * (test files and the `testing/` helpers excluded) and `frontend/package.json`.
10	 *
11	 * US-03-AC-13 / ADR-0009: no `innerHTML`, `outerHTML`, `insertAdjacentHTML`, `bypassSecurityTrust*`
12	 *   or `DomSanitizer` anywhere in the front end.
13	 * US-03-AC-15 / ADR-0008: no card, bank or payment-provider vocabulary outside the copy that says
14	 *   no charge is made; no `autocomplete` token starting with `cc-`; `SimulatedPaymentGateway` does
15	 *   not inject `HttpClient`; `sessionStorage` is referenced only by `QuoteStore`; the confirmation
16	 *   is not deferred (`@defer`) or lazy loaded; no new dependency (the list below is the one of
17	 *   the start of US-03).
18	 */
19	
20	const SRC = join(process.cwd(), 'src');
21	
22	function walk(dir: string): string[] {
23	  return readdirSync(dir).flatMap((name) => {
24	    const path = join(dir, name);
25	    return statSync(path).isDirectory() ? walk(path) : [path];
26	  });
27	}
28	
29	const isTest = (path: string): boolean => /\.spec\.ts$/.test(path) || path.includes(`${join('src', 'testing')}`);
30	const production = walk(SRC).filter((p) => /\.(ts|html)$/.test(p) && !isTest(p));
31	const read = (path: string): string => readFileSync(path, 'utf8');
32	const matches = (pattern: RegExp, files = production): string[] => files.filter((p) => pattern.test(read(p))).map((p) => p.replace(SRC, 'src'));
33	
34	describe('US-03-AC-13 / ADR-0009 the front end has no HTML string path', () => {
35	  it('US-03-AC-13 the production sources are found (the guard looks at something)', () => {
36	    expect(production.length).toBeGreaterThan(20);
37	  });
38	
39	  it('US-03-AC-13 no innerHTML, outerHTML, insertAdjacentHTML, bypassSecurityTrust or DomSanitizer in production code', () => {
40	    expect(matches(/innerHTML|outerHTML|insertAdjacentHTML|bypassSecurityTrust|DomSanitizer/)).toEqual([]);
41	  });
42	
43	  it('US-03-AC-13 the renderer exists and binds its content with interpolation only (no property or attribute binding of a span text)', () => {
44	    const files = production.filter((p) => /rich-text\.(ts|html)$/.test(p));
45	    expect(files.length).toBeGreaterThan(0);
46	    for (const file of files) {
47	      expect(read(file), file).not.toMatch(/\[(innerHTML|href|src|style|class|attr\.[a-z-]+)\]\s*=\s*"[^"]*span/);
48	    }
49	  });
